{
  "$schema": "https://opencode.ai/config.json",

  // Model Configuration
  "model": "anthropic/claude-sonnet-4-20250514",
  "small_model": "anthropic/claude-3-5-haiku-20241022",

  // Auto-update enabled
  "autoupdate": true,

  // Instructions from existing files
  "instructions": [
    "CLAUDE.md",
    ".cursor/rules/*.mdc",
    "docs/claude-guidelines/*.md"
  ],

  // MCP Servers (migrated from .mcp.json with active ones only)
  "mcp": {
    "Context7": {
      "command": "npx",
      "args": ["-y", "@upstash/context7-mcp"]
    },
    "gitmcp": {
      "command": "npx",
      "args": ["-y", "mcp-remote", "https://companytwo.example.com/docs"]
    }
  },

  // Permissions - ask before destructive operations
  "permission": {
    "edit": "ask",
    "bash": {
      "default": "ask",
      // Allow read-only operations without asking
      "allow": [
        "pnpm -w check",
        "pnpm --filter * check",
        "curl -s http://localhost:*",
        "psql -h localhost * -c 'SELECT *'",
        "git status",
        "git diff",
        "git log"
      ]
    }
  },

  // Commands for common operations
  "command": {
    "check": {
      "template": "Run type-check and linting for all packages. Fix any errors found.",
      "description": "Type-check and lint all packages"
    },
    "db-migrate": {
      "template": "Generate and run database migrations for $ARGUMENTS (backend or frontend). Make sure to review the migration files.",
      "description": "Generate and run DB migrations"
    },
    "test-api": {
      "template": "Test the API endpoint $ARGUMENTS using curl with the dev bypass token.",
      "description": "Test an API endpoint"
    }
  },

  // Sharing - manual only (security for private repo)
  "share": "disabled",

  // Formatters configuration
  "formatter": {
    "biome": {
      "command": ["pnpm", "biome", "format", "--write", "$FILE"],
      "extensions": [".js", ".ts", ".jsx", ".tsx", ".json", ".jsonc"]
    }
  }
}
